import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/BUILDING.html","title":"构建 Apollo MMORPG 框架","lang":"en-US","frontmatter":{},"filePathRelative":"BUILDING.md","git":{"createdTime":1765324273000,"updatedTime":1765325756000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":2,"url":"https://github.com/cuihairu"}]}}`),a={name:`BUILDING.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="构建-apollo-mmorpg-框架" tabindex="-1"><a class="header-anchor" href="#构建-apollo-mmorpg-框架"><span>构建 Apollo MMORPG 框架</span></a></h1><h2 id="使用-vcpkg-推荐" tabindex="-1"><a class="header-anchor" href="#使用-vcpkg-推荐"><span>使用 vcpkg（推荐）</span></a></h2><h3 id="_1-安装-vcpkg" tabindex="-1"><a class="header-anchor" href="#_1-安装-vcpkg"><span>1. 安装 vcpkg</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 克隆 vcpkg</span></span>
<span class="line"><span class="token function">git</span> clone https://github.com/microsoft/vcpkg.git</span>
<span class="line"><span class="token builtin class-name">cd</span> <span class="token function">vcpkg</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Linux/macOS</span></span>
<span class="line">./bootstrap-vcpkg.sh</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Windows</span></span>
<span class="line">.<span class="token punctuation">\\</span>bootstrap-vcpkg.bat</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-构建项目" tabindex="-1"><a class="header-anchor" href="#_2-构建项目"><span>2. 构建项目</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 返回到项目根目录</span></span>
<span class="line"><span class="token builtin class-name">cd</span> <span class="token punctuation">..</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 配置 CMake</span></span>
<span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>./vcpkg/scripts/buildsystems/vcpkg.cmake <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DVCPKG_TARGET_TRIPLET</span><span class="token operator">=</span>x64-linux <span class="token comment"># Linux</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建</span></span>
<span class="line">cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">--config</span> Release</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="使用系统包管理器" tabindex="-1"><a class="header-anchor" href="#使用系统包管理器"><span>使用系统包管理器</span></a></h2><h3 id="ubuntu-debian" tabindex="-1"><a class="header-anchor" href="#ubuntu-debian"><span>Ubuntu/Debian</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 安装依赖</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">apt-get</span> <span class="token function">install</span> nlohmann-json3-dev libprotobuf-dev protobuf-compiler libgtest-dev libfmt-dev</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建</span></span>
<span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release</span>
<span class="line">cmake <span class="token parameter variable">--build</span> build</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="macos" tabindex="-1"><a class="header-anchor" href="#macos"><span>macOS</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用 Homebrew</span></span>
<span class="line">brew <span class="token function">install</span> nlohmann-json protobuf gtest <span class="token function">fmt</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建</span></span>
<span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release</span>
<span class="line">cmake <span class="token parameter variable">--build</span> build</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="windows" tabindex="-1"><a class="header-anchor" href="#windows"><span>Windows</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用 vcpkg（推荐）</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> nlohmann-json protobuf gtest fmt:x64-windows</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建</span></span>
<span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token variable"><span class="token variable">\`</span></span>
<span class="line">  <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token variable">\`</span></span></span>
<span class="line">  <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span>./vcpkg/scripts/buildsystems/vcpkg.cmake \`</span>
<span class="line">  <span class="token parameter variable">-DVCPKG_TARGET_TRIPLET</span><span class="token operator">=</span>x64-windows</span>
<span class="line"></span>
<span class="line">cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">--config</span> Release</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="构建选项" tabindex="-1"><a class="header-anchor" href="#构建选项"><span>构建选项</span></a></h2><h3 id="cmake-选项" tabindex="-1"><a class="header-anchor" href="#cmake-选项"><span>CMake 选项</span></a></h3><ul><li><code>APOLLO_BUILD_TESTS=ON</code> - 构建单元测试（默认：ON）</li><li><code>APOLLO_BUILD_EXAMPLES=ON</code> - 构建示例程序（默认：ON）</li><li><code>APOLLO_ENABLE_COVERAGE=ON</code> - 启用代码覆盖率（需要 gcov/lcov）</li><li><code>APOLLO_ENABLE_DOXYGEN=ON</code> - 生成 API 文档（需要 Doxygen）</li><li><code>APOLLO_ENABLE_CLANG_TIDY=ON</code> - 启用 clang-tidy 静态分析</li></ul><h3 id="vcpkg-features" tabindex="-1"><a class="header-anchor" href="#vcpkg-features"><span>vcpkg Features</span></a></h3><p>vcpkg.json 定义了以下可选功能：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 安装所有依赖（默认）</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> <span class="token parameter variable">--triplet</span><span class="token operator">=</span>x64-linux</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 只安装基本依赖（不包括 Redis 和额外功能）</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> <span class="token parameter variable">--triplet</span><span class="token operator">=</span>x64-linux --x-feature<span class="token operator">=</span>basic</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 安装包含所有功能的依赖</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> <span class="token parameter variable">--triplet</span><span class="token operator">=</span>x64-linux --x-feature<span class="token operator">=</span>full</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者在 vcpkg.json 中指定要安装的 features：</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token string">&quot;dependencies&quot;</span><span class="token builtin class-name">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token string">&quot;apollo-mmorpg[tests,redis]&quot;</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可用的 features：</p><ul><li><code>tests</code> - 包含 gtest 和 gmock</li><li><code>redis</code> - Redis 客户端支持</li><li><code>protobuf</code> - Protocol Buffers 支持（包含 zlib）</li></ul><h2 id="运行测试" tabindex="-1"><a class="header-anchor" href="#运行测试"><span>运行测试</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> build</span>
<span class="line">ctest --output-on-failure <span class="token parameter variable">-C</span> Release</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="生成文档" tabindex="-1"><a class="header-anchor" href="#生成文档"><span>生成文档</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DAPOLLO_ENABLE_DOXYGEN</span><span class="token operator">=</span>ON</span>
<span class="line"><span class="token builtin class-name">cd</span> build</span>
<span class="line"><span class="token function">make</span> doc</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 文档将生成在 build/docs/html/</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="开发者指南" tabindex="-1"><a class="header-anchor" href="#开发者指南"><span>开发者指南</span></a></h2><h3 id="添加新的依赖" tabindex="-1"><a class="header-anchor" href="#添加新的依赖"><span>添加新的依赖</span></a></h3><ol><li>编辑 <code>vcpkg.json</code> 添加依赖：</li></ol><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;dependencies&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token string">&quot;nlohmann-json&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&quot;your-new-dependency&quot;</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>更新 <code>CMakeLists.txt</code>：</li></ol><div class="language-cmake line-numbers-mode" data-highlighter="prismjs" data-ext="cmake"><pre><code class="language-cmake"><span class="line"><span class="token keyword">find_package</span><span class="token punctuation">(</span>your-dependency CONFIG REQUIRED<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">target_link_libraries</span><span class="token punctuation">(</span>apollo <span class="token namespace">PRIVATE</span> your-<span class="token inserted class-name">dependency::your</span>-dependency<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>安装新依赖：</li></ol><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> <span class="token function">vcpkg</span></span>
<span class="line">./vcpkg <span class="token function">install</span> your-dependency</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="windows-开发提示" tabindex="-1"><a class="header-anchor" href="#windows-开发提示"><span>Windows 开发提示</span></a></h3><ul><li>使用 Visual Studio 2019 或更新版本</li><li>安装 CMake 工具</li><li>使用 x64 Native Tools Command Prompt</li><li>考虑使用 CLion 进行开发</li></ul><h3 id="linux-开发提示" tabindex="-1"><a class="header-anchor" href="#linux-开发提示"><span>Linux 开发提示</span></a></h3><ul><li>推荐使用 CLion 或 VSCode + CMake 插件</li><li>安装 clang-tidy 用于静态分析</li><li>使用 valgrind 进行内存检查</li></ul><h2 id="故障排除" tabindex="-1"><a class="header-anchor" href="#故障排除"><span>故障排除</span></a></h2><h3 id="找不到依赖" tabindex="-1"><a class="header-anchor" href="#找不到依赖"><span>找不到依赖</span></a></h3><p>如果 CMake 找不到依赖，请确保：</p><ol><li>vcpkg 已正确安装依赖</li><li><code>CMAKE_TOOLCHAIN_FILE</code> 路径正确</li><li>使用正确的 <code>VCPKG_TARGET_TRIPLET</code></li></ol><h3 id="windows-特定问题" tabindex="-1"><a class="header-anchor" href="#windows-特定问题"><span>Windows 特定问题</span></a></h3><ol><li>确保 Python 已安装（vcpkg 需要）</li><li>使用 x64 工具链</li><li>可能需要安装 Visual Studio Build Tools</li></ol><h3 id="macos-特定问题" tabindex="-1"><a class="header-anchor" href="#macos-特定问题"><span>macOS 特定问题</span></a></h3><ol><li>更新 Xcode 到最新版本</li><li>安装 Xcode Command Line Tools</li></ol><h2 id="性能优化建议" tabindex="-1"><a class="header-anchor" href="#性能优化建议"><span>性能优化建议</span></a></h2><ol><li>使用 Release 构建进行性能测试</li><li>启用编译器优化：<code>-O3 -march=native</code></li><li>使用 LTO（链接时优化）：<code>-DCMAKE_INTERPROCEDURAL_OPTIMIZATION=ON</code></li><li>使用静态链接以减少依赖：<code>-DCMAKE_MSVC_RUNTIME_LIBRARY=MultiThreaded</code></li></ol>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};